// ============================================================
// Ktoré nášivky sú v Shoptete povolené
// ============================================================
// Michal 2026-09-01: „Nášivky v konfigurátore musia reagovať na to, ktoré sú
// povolené — ja som ich v Shoptete povypínal, ale stále ich ponúka."
// Zoznam NASIVKY je tu natvrdo (kód + náhľad); Shoptet vie len to, ktoré
// hodnoty príplatkového parametra má admin zapnuté. Preto ho pri renderi
// prefiltrujeme podľa `<select>`-ov na stránke produktu. Číta sa raz pri
// mounte — Shoptet parametre počas života stránky nemení.
function usePovoleneNasivky() {
  return useMemo(() => {
    try {
      return povoleneNasivkyVsade();
    } catch (e) {
      // radšej ponúknuť všetko než spadnúť na prázdnej mriežke
      return { boky: null, stred: null, dvere: null };
    }
  }, []);
}


// ============================================================
// COMPONENTS
// ============================================================

function ChevronDown({ open }) {
  return (
    <svg width="20" height="20" viewBox="0 0 20 20" fill="none"
      style={{ transform: open ? "rotate(180deg)" : "rotate(0deg)", transition: "transform 0.3s" }}>
      <path d="M5 7.5L10 12.5L15 7.5" stroke="white" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
    </svg>
  );
}

function Dropdown({ label, value, options, onChange, color, icon, placeholder }) {
  const [isOpen, setIsOpen] = useState(false);
  // Neutralny jednotny styl — biele pozadie, sede/zlate ramceky, bez per-field tintu
  const BORDER_IDLE = "#ddd";
  const BORDER_ACTIVE = "#C5A44E";
  const ACCENT = "#C5A44E";
  return (
    <div style={{ marginBottom: 16, position: "relative", zIndex: isOpen ? 100 : 1 }}>
      <div style={{ fontSize: 12, fontWeight: 600, color: "#555", marginBottom: 6, display: "flex", alignItems: "center", gap: 6 }}>
        {icon && <span>{icon}</span>}
        {label}
      </div>
      <div style={{ position: "relative" }}>
        <div
          onClick={() => setIsOpen(!isOpen)}
          style={{
            border: `2px solid ${value ? BORDER_ACTIVE : BORDER_IDLE}`,
            borderRadius: 8,
            padding: "14px 44px 14px 14px",
            cursor: "pointer",
            background: "#fff",
            fontSize: 16,
            color: value ? "#333" : "#999",
            transition: "all 0.2s",
            userSelect: "none",
            minHeight: 28,
          }}
        >
          {value || placeholder || "Vyberte..."}
          <div style={{ position: "absolute", right: 12, top: "50%", transform: "translateY(-50%)" }}>
            <svg width="16" height="16" viewBox="0 0 16 16">
              <path d={isOpen ? "M4 10L8 6L12 10" : "M4 6L8 10L12 6"} stroke="#999" strokeWidth="2" fill="none" strokeLinecap="round"/>
            </svg>
          </div>
        </div>
        {isOpen && (
          <>
            <div onClick={() => setIsOpen(false)} style={{ position: "fixed", top: 0, left: 0, right: 0, bottom: 0, zIndex: 999 }} />
            <div style={{
              position: "absolute", top: "100%", left: 0, right: 0, zIndex: 1000,
              background: "#fff", border: "2px solid #ddd", borderRadius: 8,
              boxShadow: "0 8px 24px rgba(0,0,0,0.15)", marginTop: 4,
              maxHeight: 300, overflowY: "auto",
            }}>
              {options.map((opt) => (
                <div key={opt} onClick={() => { onChange(opt); setIsOpen(false); }}
                  style={{
                    padding: "14px 14px", cursor: "pointer", fontSize: 15,
                    background: opt === value ? "#fdf8ec" : "#fff",
                    borderLeft: opt === value ? `4px solid ${ACCENT}` : "4px solid transparent",
                    transition: "all 0.15s",
                    minHeight: 28,
                  }}
                  onMouseOver={(e) => { if (opt !== value) e.target.style.background = "#f5f5f5"; }}
                  onMouseOut={(e) => { if (opt !== value) e.target.style.background = "#fff"; }}
                >
                  {opt}
                </div>
              ))}
            </div>
          </>
        )}
      </div>
    </div>
  );
}

function AccordionSection({ number, title, subtitle, open, done, onClick, children, error, errorMessage }) {
  const [keepContentMounted, setKeepContentMounted] = useState(open);
  const [allowContentOverflow, setAllowContentOverflow] = useState(open);
  React.useEffect(() => {
    if (open) {
      setKeepContentMounted(true);
      return undefined;
    }
    const timer = setTimeout(() => setKeepContentMounted(false), 480);
    return () => clearTimeout(timer);
  }, [open]);
  React.useEffect(() => {
    if (!open) {
      setAllowContentOverflow(false);
      return undefined;
    }
    // Po dokončení animácie výšky musí byť obsah visible, inak sa rozbalené
    // dropdowny pri spodnej hrane akordeónu fyzicky orežú.
    const timer = setTimeout(() => setAllowContentOverflow(true), 470);
    return () => clearTimeout(timer);
  }, [open]);

  // Determine header background
  let headerBg = "linear-gradient(135deg, #C5A44E, #A8893A)"; // default gold
  if (done) headerBg = "linear-gradient(135deg, #4CAF50, #388E3C)"; // green when complete

  // Unified border color for the whole accordion
  const borderColor = error ? "#CC0000" : "#e0d5b8";

  return (
    <div id={`konfig-step-${number}`} style={{
      marginBottom: 8, scrollMarginTop: 20,
      position: "relative",
      zIndex: open ? 2 : 1,
      borderRadius: 10,
      border: error ? `3px solid ${borderColor}` : open ? `2px solid #e0d5b8` : "none",
      boxShadow: error ? "0 0 12px rgba(204,0,0,0.25)" : "none",
      transition: "all 0.3s",
    }}>
      <div
        onClick={onClick}
        style={{
          background: headerBg,
          color: "#fff",
          padding: "16px 16px",
          borderRadius: !open ? (error ? 7 : 10) : (error ? "7px 7px 0 0" : "8px 8px 0 0"),
          cursor: "pointer",
          display: "flex",
          alignItems: "center",
          gap: 10,
          userSelect: "none",
          transition: "all 0.3s",
          minHeight: 48,
        }}
      >
        <div style={{
          width: 36, height: 36, borderRadius: "50%",
          background: error ? "rgba(255,255,255,0.35)" : "rgba(255,255,255,0.2)", display: "flex",
          alignItems: "center", justifyContent: "center",
          fontWeight: 700, fontSize: 19,
        }}>
          {done ? "✓" : number}
        </div>
        <div style={{ flex: 1 }}>
          <span style={{ fontWeight: 700, fontSize: 18, letterSpacing: 1, textTransform: "uppercase" }}>
            {title}
          </span>
          {!open && error && errorMessage && (
            <div style={{ fontSize: 15, fontWeight: 700, opacity: 1, marginTop: 4, display: "flex", alignItems: "center", gap: 6 }}>
              ⚠ {errorMessage} — kliknite sem
            </div>
          )}
          {!open && !error && subtitle && (
            <div style={{ fontSize: 14, fontWeight: 400, opacity: 0.9, marginTop: 3 }}>
              {subtitle}
            </div>
          )}
        </div>
        {!open && done && !error && (
          <div style={{
            padding: "6px 16px", borderRadius: 6,
            background: "rgba(255,255,255,0.35)", fontSize: 13, fontWeight: 700,
            letterSpacing: 0.5, textTransform: "uppercase",
            border: "1px solid rgba(255,255,255,0.5)",
          }}>Zmeniť</div>
        )}
        <ChevronDown open={open} />
      </div>
      {/* Red hint banner when section is open and has error */}
      {open && error && errorMessage && (
        <div style={{
          background: "#FFEBEE",
          padding: "12px 16px", fontSize: 14, color: "#CC0000",
          fontWeight: 700, display: "flex", alignItems: "center", gap: 10,
          borderTop: "1px solid #CC0000",
        }}>
          <span style={{ fontSize: 22 }}>👇</span> {errorMessage}
        </div>
      )}
      <div style={{
        display: "grid",
        gridTemplateRows: open ? "1fr" : "0fr",
        overflow: allowContentOverflow ? "visible" : "hidden",
        transition: "grid-template-rows 0.46s cubic-bezier(0.22, 1, 0.36, 1)",
        background: "#fff",
        borderRadius: error ? "0 0 7px 7px" : "0 0 8px 8px",
      }}>
        <div style={{ minHeight: 0, overflow: allowContentOverflow ? "visible" : "hidden" }}>
          <div style={{
            padding: open ? "22px 16px" : "0 16px",
            opacity: open ? 1 : 0,
            transform: open ? "none" : "translateY(-6px)",
            transition: "padding 0.46s cubic-bezier(0.22, 1, 0.36, 1), opacity 0.2s ease, transform 0.3s ease",
          }}>
            {(open || keepContentMounted) && children}
          </div>
        </div>
      </div>
    </div>
  );
}

// Plynule prepne hlavny akordeon a pocas zmeny vysky dorovnava scroll.
// Samostatny oneskoreny scrollIntoView po dokonceni animacie sposoboval druhy
// skok; priebezne meranie cielovej hlavicky udrzi novu sekciu na jednom mieste.
function useAccordionTransition(openSection, setOpenSection) {
  const frameRef = React.useRef(0);
  const openSectionRef = React.useRef(openSection);
  openSectionRef.current = openSection;

  React.useEffect(() => () => cancelAnimationFrame(frameRef.current), []);

  return React.useCallback((nextSection) => {
    cancelAnimationFrame(frameRef.current);

    const current = document.getElementById(`konfig-step-${openSectionRef.current}`);
    const currentTop = current ? current.getBoundingClientRect().top : 20;
    const viewportHeight = window.innerHeight || 800;
    const anchorTop = currentTop >= 12 && currentTop <= viewportHeight * 0.65 ? currentTop : 20;
    const reducedMotion = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    const duration = reducedMotion ? 0 : 500;
    let startedAt = null;

    setOpenSection(nextSection);

    const keepTargetAnchored = (now) => {
      const target = document.getElementById(`konfig-step-${nextSection}`);
      if (!target) return;
      if (startedAt === null) startedAt = now;

      const elapsed = now - startedAt;
      const progress = duration ? Math.min(1, elapsed / duration) : 1;
      const delta = target.getBoundingClientRect().top - anchorTop;
      const correction = progress === 1 ? delta : delta * (0.12 + progress * 0.28);
      if (Math.abs(correction) > 0.25) window.scrollBy(0, correction);

      if (progress < 1) {
        frameRef.current = requestAnimationFrame(keepTargetAnchored);
      } else if (Math.abs(target.getBoundingClientRect().top - anchorTop) > 0.5) {
        window.scrollBy(0, target.getBoundingClientRect().top - anchorTop);
      }
    };

    frameRef.current = requestAnimationFrame(() => {
      frameRef.current = requestAnimationFrame(keepTargetAnchored);
    });
  }, [setOpenSection]);
}

function Summary({ selections }) {
  const items = [
    { label: "Značka", value: selections.znacka, color: "#C5A44E" },
    { label: "Model", value: selections.model, color: "#C5A44E" },
  ];
  FIELD_ORDER.forEach((key) => {
    if (selections[key]) {
      items.push({ label: FIELD_META[key].label, value: selections[key], color: FIELD_META[key].color });
    }
  });
  return (
    <div style={{ background: "#f9f7f2", borderRadius: 10, padding: 20, border: "2px solid #e0d5b8" }}>
      <div style={{ fontWeight: 700, fontSize: 14, color: "#333", marginBottom: 12, textTransform: "uppercase", letterSpacing: 1 }}>
        Vaša konfigurácia
      </div>
      {items.map((item, i) => (
        <div key={i} style={{ display: "flex", marginBottom: 6, fontSize: 14 }}>
          <span style={{ color: "#888", width: 140, flexShrink: 0 }}>{item.label}:</span>
          <span style={{ color: item.color, fontWeight: 600 }}>{item.value}</span>
        </div>
      ))}
    </div>
  );
}

